    cvals = [i - a[i] for i in range(n)]

    bpos = {}
    cpos = {}
    for i in range(n):
        bpos.setdefault(bvals[i], []).append(i)
        cpos.setdefault(cvals[i], []).append(i)

    prev = [-1] * n
    stack = []
    for i in range(n):
        while stack and times[stack[-1]] >= times[i]:
            stack.pop()
        if stack:
            prev[i] = stack[-1]
        stack.append(i)

    nxt = [n] * n
    stack.clear()
    for i in range(n - 1, -1, -1):
        while stack and times[stack[-1]] >= times[i]:
            stack.pop()
        if stack:
            nxt[i] = stack[-1]
        stack.append(i)

    intervals = set()
    parent = {}
    for x in removed:
        x -= 1
        left = prev[x] + 1
        right = nxt[x] - 1
        parent[x] = (left, right)
        intervals.add((left, right))
        if left < x:
            intervals.add((left, x - 1))
        if x < right:
            intervals.add((x + 1, right))

    if q == 0:
        intervals.add((0, n - 1))
    else:
        deleted = sorted(x - 1 for x in removed)
        start = 0
        for x in deleted:
            if start < x:
                intervals.add((start, x - 1))
            start = x + 1
        if start < n:
            intervals.add((start, n - 1))

    queries = list(intervals)
    block = max(1, int(n / sqrt(max(1, len(queries)))))
    queries.sort(key=lambda p: (p[0] // block, p[1] if (p[0] // block) % 2 == 0 else -p[1]))

    answers = {}
    cur_l, cur_r = 0, -1
    total = 0

    def count_key(mapping, key, lo, hi):
        if lo > hi:
            return 0
        arr = mapping.get(key)
        if arr is None:
            return 0
        return bisect_right(arr, hi) - bisect_left(arr, lo)

    def incident(x, lo, hi):
        if lo > hi:
            return 0

        bx = bvals[x]
        cx = cvals[x]

        res = count_key(bpos, bx - k, max(lo, x - k), x - 1)
        res += count_key(bpos, bx + k, x + 1, min(hi, x + k))
        res += count_key(cpos, cx - k, max(lo, x - k + 1), x - 1)
        res += count_key(cpos, cx + k, x + 1, min(hi, x + k - 1))
        return res

    def add_left(x):
        nonlocal total, cur_l
        total += incident(x, cur_l, cur_r)
        cur_l = x

    def add_right(x):
        nonlocal total, cur_r
        total += incident(x, cur_l, cur_r)
        cur_r = x

    def remove_left():
        nonlocal total, cur_l
        x = cur_l
        total -= incident(x, cur_l + 1, cur_r)
        cur_l += 1

    def remove_right():
        nonlocal total, cur_r
        x = cur_r
        total -= incident(x, cur_l, cur_r - 1)
        cur_r -= 1

    for left, right in queries:
        while cur_l > left:
            add_left(cur_l - 1)
        while cur_r < right:
            add_right(cur_r + 1)
        while cur_l < left:
            remove_left()
        while cur_r > right:
            remove_right()
        answers[(left, right)] = total

    if q == 0:
        sys.stdout.write(str(answers[(0, n - 1)]))
        return

    out = [str(answers[(0, n - 1)])]
    current = int(out[0])

    for x0 in removed:
        x = x0 - 1
        left, right = parent[x]
        lost = answers[(left, right)]
        if left < x:
            lost -= answers[(left, x - 1)]
        if x < right:
            lost -= answers[(x + 1, right)]
        current -= lost
        out.append(str(current))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
